contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount > 0);

        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        bool withdrawExactReverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrawExactReverted = true;
        } else {
            withdrawExactReverted = false;
        }

        bool withdrawExcessReverted;
        c.withdraw(1); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            withdrawExcessReverted = true;
        } else {
            withdrawExcessReverted = false;
        }

        assert(!withdrawExactReverted && withdrawExcessReverted);
    }

    receive() external payable {}
}

